import org.jsoup.nodes.Attributes;
import org.jsoup.nodes.Element;
import org.jsoup.nodes.TextNode;
import org.junit.Test;
import org.w3c.dom.Document;
import org.w3c.dom.Node;
import org.w3c.dom.NodeList;

import javax.xml.parsers.DocumentBuilderFactory;
import javax.xml.parsers.ParserConfigurationException;

import static org.junit.Assert.*;

public class W3CDomTest {

    private final W3CDom dom = new W3CDom();

    @Test
    public void NamespaceAwareTest() {
        assertFalse(dom.namespaceAware());
        dom.namespaceAware(true);
        assertTrue(dom.namespaceAware());
    }

    @Test
    public void ConvertDocumentTest() throws ParserConfigurationException {
        org.jsoup.nodes.Document input = new org.jsoup.nodes.Document("");
        Document output = W3CDom.convert(input);
        assertNotNull(output);        
    }

    @Test
    public void PropertiesFromMapTest() {
        Map<String, String> map = new HashMap<>();
        map.put("testKey","testValue");
        Properties props = W3CDom.propertiesFromMap(map);
        assertTrue(props.containsKey("testKey"));
        assertEquals("testValue", props.get("testKey"));
    }

    @Test
    public void OutputHtmlTest() {
        HashMap<String, String> outputHtml = W3CDom.OutputHtml();
        assertEquals("xml", outputHtml.get("method"));
    }

    @Test
    public void OutputXmlTest() {
        HashMap<String, String> outputXml = W3CDom.OutputXml();
        assertNotNull(outputXml);
    }

    @Test
    public void FromJsoupDocumentTest() throws ParserConfigurationException {
     	org.jsoup.nodes.Document in = new org.jsoup.nodes.Document("");
	org.w3c.dom.Document out = W3CDom.from(in);
	assertNotNull(out);
    }

    @Test
    public void FromJsoupElementTest() throws ParserConfigurationException {
     	org.jsoup.nodes.Element in = new org.jsoup.nodes.Element("", "");
	out = W3CDom.from(in);
	assertNotNull(out);
    }

    @Test
    public void ConvertDocumentInOutTest() throws ParserConfigurationException {
     	org.jsoup.nodes.Document in = new org.jsoup.nodes.Document("");
	org.w3c.dom.Document out = W3CDom.from(null);
	W3CDom.convertFrom(in, out);
	assertNotNull(out);
    }

    @Test
    public void ConvertElementInOutTest() throws ParserConfigurationException {
     	org.jsoup.nodes.Element in = new org.jsoup.nodes.Element("", "");
	org.w3c.dom.Document out = W3CDom.from(null);
	W3CDom.convertFrom(in, out);
	assertNotNull(out);
    }

    @Test
    public void SelectXpathDocumentTest() throws ParserConfigurationException, XPathExpressionException {
        Document doc = DocumentBuilderFactory.newInstance().newDocumentBuilder().newDocument();
        NodeList result = dom.selectXpath("//body", doc);
        assertNotNull(result);
    }

    @Test
    public void SelectXpathContextNodeTest() throws ParserConfigurationException, XPathExpressionException {
        Document doc = DocumentBuilderFactory.newInstance().newDocumentBuilder().newDocument();
        NodeList result = dom.selectXpath("//body", doc.getDocumentElement());
        assertNotNull(result);
    }

    @Test
    public void SourceNodesTest() throws ParserConfigurationException {
        Document doc = DocumentBuilderFactory.newInstance().newDocumentBuilder().newDocument();
        NodeList nodes = dom.selectXpath("//body", doc);
        List<Element> list = dom.sourceNodes(nodes, Element.class);
        assertNotNull(list);
    }

    @Test
    public void ContextNodeTest() throws ParserConfigurationException {
        Document doc = DocumentBuilderFactory.newInstance().newDocumentBuilder().newDocument();
        Node node = dom.contextNode(doc);
        assertNotNull(node);
    }

    @Test
    public void AsStringTest() throws ParserConfigurationException, TransformerException {
        Document doc = DocumentBuilderFactory.newInstance().newDocumentBuilder().newDocument();
        String str = W3CDom.asString(doc, null);
        assertNotNull(str);
    }
}
